// German B2 practice rooms: 6 modules x 12 rooms x 3 questions.
window.deRooms = window.deRooms || {};
deRooms.B2 = [
  // Module 1: Debate & Argumentation
  [
    {t:"Debate key words",s:"Vocabulary",qs:[
      {q:"What does 'widerlegen' mean?",opts:["to refute","to confirm","to postpone","to summarise"],a:0,ex:"'Widerlegen' means proving an argument wrong; 'wider-' means 'against', as in 'widersprechen'."},
      {q:"What is 'das Gegenargument'?",opts:["the counter-argument","the main argument","the agreement","the conclusion"],a:0,ex:"'Gegen' means 'against', so a Gegenargument is the point raised against your position."},
      {q:"Which verb means 'to weigh up' (pros and cons)?",opts:["abwägen","abwaschen","abbiegen","abgeben"],a:0,ex:"'Abwägen' comes from 'die Waage' (scales): you weigh one side against the other."}
    ]},
    {t:"Adding weight: zudem & co",s:"Vocabulary",qs:[
      {q:"Which word means 'moreover / in addition'?",opts:["zudem","trotzdem","sondern","damit"],a:0,ex:"'Zudem' adds a further argument, like 'außerdem' or the more formal 'ferner'."},
      {q:"In 'Ich bleibe zu Hause, zumal es regnet', what does 'zumal' mean?",opts:["especially since","even though","as soon as","provided that"],a:0,ex:"'Zumal' gives an extra, reinforcing reason, so it means 'especially since / all the more as'."},
      {q:"Which verb is the opposite of 'zustimmen' (to agree)?",opts:["widersprechen","zuhören","beitragen","vorschlagen"],a:0,ex:"'Widersprechen' means to contradict someone, the opposite of agreeing with them."}
    ]},
    {t:"Stress in debate words",s:"Pronunciation",qs:[
      {q:"Listen. Which syllable is stressed in 'Argument'?",say:"das Argument",opts:["the last: -ment","the first: Ar-","the middle: -gu-","all equally"],a:0,ex:"Many Latin loanwords in German stress the final syllable: Argu-MENT, Instru-MENT, Doku-MENT."},
      {q:"Listen. Which syllable is stressed in 'widerlegen'?",say:"widerlegen",opts:["-le-","wi-","-der-","-gen"],a:0,ex:"'Widerlegen' is inseparable, so the stress falls on the verb stem: wider-LE-gen."},
      {q:"Listen. How is the 'z' in 'zwar' pronounced?",say:"zwar",opts:["like 'ts' in 'cats'","like 's' in 'zoo'","like 'sh' in 'show'","like 'ch' in 'chin'"],a:0,ex:"German 'z' is always pronounced 'ts', so 'zwar' starts with the sounds t-s-v."}
    ]},
    {t:"Zwar ..., aber ...",s:"Grammar",qs:[
      {q:"Fill the gap: 'Zwar ___ das Projekt teuer, aber es lohnt sich.'",opts:["ist","es ist","sei","sein"],a:0,ex:"'Zwar' at the start fills position 1, so the conjugated verb 'ist' must come next, before the subject."},
      {q:"Which word normally introduces the counterpoint after 'zwar'?",opts:["aber","oder","denn","sondern"],a:0,ex:"The concessive pair is 'zwar ... aber': admit a point, then counter it; 'sondern' only follows a negation."},
      {q:"Fill the gap: 'Einerseits ist die Stadt laut, ___ ist sie sehr lebendig.'",opts:["andererseits","außerdem","deshalb","trotzdem"],a:0,ex:"'Einerseits' (on the one hand) is completed by 'andererseits' (on the other hand)."}
    ]},
    {t:"Concession in harder sentences",s:"Grammar",qs:[
      {q:"Which sentence is correct?",opts:["Das Auto ist zwar alt, aber es fährt noch gut.","Das Auto zwar ist alt, aber es fährt noch gut.","Das Auto ist zwar alt, aber fährt es noch gut.","Zwar das Auto ist alt, aber es fährt noch gut."],a:0,ex:"'Zwar' can sit after the verb; 'aber' takes no position, so the next clause keeps normal order: es fährt."},
      {q:"Complete: 'Ich komme mit, zumal ___.'",opts:["ich morgen frei habe","habe ich morgen frei","ich habe morgen frei","morgen ich frei habe"],a:0,ex:"'Zumal' is a subordinating conjunction, so the conjugated verb goes to the end of the clause."},
      {q:"Fill the gap: 'Fakt ist, ___ die Mieten stark gestiegen sind.'",opts:["dass","das","ob","wie"],a:0,ex:"'Fakt ist, dass ...' introduces a statement of fact with the conjunction 'dass' (double s)."}
    ]},
    {t:"Reading: forum comments",s:"Reading",qs:[
      {q:"'Zwar ist ein Tempolimit unpopulär, aber es würde Leben retten. Zudem sinkt der Verbrauch.' What is the writer's position?",opts:["in favour of a speed limit","against a speed limit","undecided about it","only for limits in cities"],a:0,ex:"The writer concedes the limit is unpopular, then gives two arguments for it: lives saved and lower consumption."},
      {q:"'Einerseits bietet Homeoffice Flexibilität, andererseits fehlt vielen der Kontakt zu Kollegen. Man muss abwägen.' What does the writer do?",opts:["weighs up both sides","rejects working from home","demands a return to the office","praises the colleagues"],a:0,ex:"'Einerseits ... andererseits' plus 'abwägen' shows a balanced view of advantages and disadvantages."},
      {q:"In a debate someone replies: 'Das mag sein, jedoch zeigen die Zahlen etwas anderes.' What is the speaker doing?",opts:["conceding, then contradicting","agreeing completely","asking for more numbers","changing the subject"],a:0,ex:"'Das mag sein' grants the point for a moment; 'jedoch' then introduces the contradiction."}
    ]},
    {t:"Listening: debate snippets",s:"Listening",qs:[
      {q:"Listen. What does the speaker add to the discussion?",say:"Ich verstehe den Punkt, würde aber ergänzen, dass die Kosten zu hoch sind.",opts:["The costs are too high.","The point is irrelevant.","The costs are lower than expected.","They fully agree."],a:0,ex:"'Würde aber ergänzen' softly adds a new point: here that the costs are too high."},
      {q:"Listen. How certain is the speaker?",say:"Es steht außer Frage, dass wir handeln müssen.",opts:["completely certain","rather unsure","slightly doubtful","against acting"],a:0,ex:"'Es steht außer Frage' means 'it is beyond question', a strong claim with no doubt."},
      {q:"Listen. According to the speaker, what has improved?",say:"Zwar sind die Tickets teurer geworden, aber der Service ist besser.",opts:["the service","the ticket prices","the timetable","the ticket design"],a:0,ex:"The concession is about prices rising; the counterpoint after 'aber' is that the service is better."}
    ]},
    {t:"Moderating a debate",s:"Speaking",qs:[
      {q:"As moderator, you give the floor to Ms Weber. What do you say?",opts:["Frau Weber, Sie haben das Wort.","Frau Weber, Sie haben die Antwort.","Frau Weber, Sie nehmen den Platz.","Frau Weber, Sie sind gewesen dran."],a:0,ex:"'Jemandem das Wort geben' / 'Sie haben das Wort' is the fixed phrase for letting someone speak."},
      {q:"Someone says 'Homeoffice macht faul.' You partly concede, then disagree. Best reply?",opts:["Das mag sein, jedoch arbeiten viele zu Hause effizienter.","Das stimmt genau, deshalb arbeite ich nur im Büro.","Das mag sein, deshalb stimme ich Ihnen völlig zu.","Fakt ist, dass Sie damit völlig recht haben."],a:0,ex:"'Das mag sein, jedoch ...' grants the point briefly and then puts a counter-argument."},
      {q:"You want to interrupt politely in a discussion. What do you say?",opts:["Darf ich kurz einhaken?","Darf ich kurz aufhören?","Muss ich kurz einhaken?","Darf ich kurz abhaken?"],a:0,ex:"'Einhaken' means to cut in on a point; 'abhaken' means to tick something off a list."}
    ]},
    {t:"Writing an argument",s:"Writing",qs:[
      {q:"Choose the correctly written sentence.",opts:["Es steht außer Frage, dass wir handeln müssen.","Es steht ausser Frage, das wir handeln müssen.","Es steht außer Frage, dass wir müssen handeln.","Es steht außer Frage dass wir handeln müssen."],a:0,ex:"The conjunction is 'dass', it needs a comma before it, and the conjugated verb goes to the end."},
      {q:"Fill the gap in the essay: 'Dieses Argument halte ich für schwach. Ich möchte es ___ widerlegen.'",opts:["im Folgenden","im Folgend","in Folgende","folgendem"],a:0,ex:"'Im Folgenden' (in what follows) is the fixed essay phrase; it is a nominalised adjective with a capital F."},
      {q:"Which sentence has the correct word order?",opts:["Ferner ist zu bedenken, dass die Kosten steigen.","Ferner zu bedenken ist, dass die Kosten steigen.","Ferner es ist zu bedenken, dass die Kosten steigen.","Ferner ist bedenken zu, dass die Kosten steigen."],a:0,ex:"'Ferner' takes position 1, so the verb 'ist' follows directly; 'zu bedenken' stays together."}
    ]},
    {t:"Debate culture",s:"Culture",qs:[
      {q:"In a formal German debate, how do you address an opponent you don't know?",opts:["with Sie and the surname","with du and the first name","with the first name only","with 'Kollege' and du"],a:0,ex:"Formal public debates use 'Sie' plus 'Herr/Frau' and the surname, even when people disagree sharply."},
      {q:"Which phrase softens disagreement in a German meeting?",opts:["Ich sehe das etwas anders.","Das ist doch völliger Unsinn.","Da irren Sie sich total.","Das ist ganz klar falsch."],a:0,ex:"'Ich sehe das etwas anders' signals disagreement politely; the others attack the other person directly."},
      {q:"What is a 'Streitgespräch'?",opts:["a debate between opposing views","a trial in a court of law","a fight out in the street","a vote taken in parliament"],a:0,ex:"A Streitgespräch is a discussion, often in media or school, where two sides argue their positions."}
    ]},
    {t:"Debate review",s:"Review",qs:[
      {q:"'Wir müssen die Risiken sorgfältig abwägen.' What does 'abwägen' mean here?",opts:["to weigh up","to reduce","to ignore","to measure"],a:0,ex:"'Abwägen' means to consider carefully which side is heavier, i.e. to weigh up pros and cons."},
      {q:"Which pair completes: '___ ist die Idee gut, ___ fehlt das Geld.'?",opts:["Einerseits ... andererseits","Zwar ... sondern","Entweder ... aber","Sowohl ... andererseits"],a:0,ex:"'Einerseits ... andererseits' contrasts two sides; both words fill position 1, so the verb follows."},
      {q:"Which sentence refutes a counter-argument?",opts:["Dieses Gegenargument lässt sich leicht widerlegen.","Dieses Gegenargument ist völlig richtig.","Dieses Argument unterstütze ich voll.","Zu diesem Punkt habe ich keine Meinung."],a:0,ex:"To refute ('widerlegen') is to show that an argument is wrong; the others agree or stay neutral."}
    ]},
    {t:"Challenge: debate moves",s:"Challenge",qs:[
      {q:"Fill the gap: 'Die Maßnahme ist sinnvoll, ___ sie kaum etwas kostet.'",opts:["zumal","zwar","zudem","ferner"],a:0,ex:"Only 'zumal' is a subordinating conjunction that sends the verb 'kostet' to the end of the clause."},
      {q:"Which sentence is grammatically correct?",opts:["Zwar mag das stimmen, jedoch überzeugt mich das nicht.","Zwar mag stimmen das, jedoch überzeugt mich das nicht.","Zwar das mag stimmen, jedoch überzeugt mich das nicht.","Zwar mag das stimmen, jedoch mich überzeugt das nicht."],a:0,ex:"'Zwar' and 'jedoch' are adverbs here, each filling position 1, so the verb follows directly."},
      {q:"In a debate someone says: 'Der Vergleich hinkt.' What do they mean?",opts:["The comparison is flawed.","The comparison is too slow.","The comparison is too long.","The comparison is convincing."],a:0,ex:"'Hinken' literally means to limp; a comparison that 'limps' does not fit the case properly."}
    ]}
  ],
  // Module 2: Passive Voice & Register
  [
    {t:"Register words",s:"Vocabulary",qs:[
      {q:"What does 'umgangssprachlich' mean?",opts:["colloquial","elevated","old-fashioned","regional"],a:0,ex:"'Die Umgangssprache' is everyday spoken language, so 'umgangssprachlich' means colloquial."},
      {q:"Describing language, what does 'gehoben' mean?",opts:["elevated / formal","vulgar / rude","technical / specialist","simple / plain"],a:0,ex:"'Gehoben' literally means 'raised'; dictionaries use it for formal, refined style."},
      {q:"Which verb is the formal equivalent of colloquial 'kriegen' (to get)?",opts:["erhalten","kriechen","kaufen","kommen"],a:0,ex:"'Kriegen' is casual; in letters and official texts you write 'erhalten' or 'bekommen'."}
    ]},
    {t:"Formal vs. casual pairs",s:"Vocabulary",qs:[
      {q:"Which is the neutral equivalent of colloquial 'kapieren'?",opts:["verstehen","kassieren","kaputtgehen","kopieren"],a:0,ex:"'Kapieren' is a casual word for understanding; the neutral verb is 'verstehen'."},
      {q:"Which word is a colloquial equivalent of 'sich unterhalten' (to chat)?",opts:["quatschen","quietschen","quälen","quittieren"],a:0,ex:"'Quatschen' is everyday speech for chatting; 'quietschen' means to squeak."},
      {q:"Which verb is a more formal alternative to casual 'gucken' (to look at)?",opts:["betrachten","betreiben","betreten","betreuen"],a:0,ex:"'Betrachten' means to look at closely; it suits written, formal register better than 'gucken'."}
    ]},
    {t:"Stress in long words",s:"Pronunciation",qs:[
      {q:"Listen. Which syllable is stressed in 'unterschrieben'?",say:"unterschrieben",opts:["-schrie-","un-","-ter-","-ben"],a:0,ex:"'Unterschreiben' is inseparable here, so the stress is on the stem: unter-SCHRIE-ben."},
      {q:"Listen. Where is the main stress in 'umgangssprachlich'?",say:"umgangssprachlich",opts:["on um-","on -gangs-","on -sprach-","on -lich"],a:0,ex:"Compounds stress the first element, and 'Umgang' stresses its prefix: UM-gangs-sprach-lich."},
      {q:"Listen. How is the 'ö' in 'gelöst' pronounced?",say:"Das Problem ist gelöst.",opts:["a long 'e' said with rounded lips","like 'o' in English 'go'","like 'u' in English 'cut'","it is silent"],a:0,ex:"Long 'ö' is made by saying 'e' as in 'Weg' while rounding the lips."}
    ]},
    {t:"werden + Partizip II",s:"Grammar",qs:[
      {q:"Fill the gap: 'Das Haus ___ gerade gebaut.'",opts:["wird","ist","hat","würde"],a:0,ex:"The Vorgangspassiv (process) uses 'werden' + Partizip II; 'gerade' shows the action is in progress."},
      {q:"What is the passive of 'Man repariert das Auto.'?",opts:["Das Auto wird repariert.","Das Auto hat repariert.","Das Auto wird reparieren.","Das Auto ist reparierend."],a:0,ex:"The object becomes the subject, and the verb becomes 'werden' + Partizip II."},
      {q:"What does 'Der Vertrag ist unterschrieben.' express?",opts:["a finished state","an ongoing process","a future plan","a polite request"],a:0,ex:"'Sein' + Partizip II is the Zustandspassiv: it describes the result after the action is done."}
    ]},
    {t:"Passive in all tenses",s:"Grammar",qs:[
      {q:"Perfect passive: 'Der Brief ___ gestern abgeschickt ___.'",opts:["ist ... worden","hat ... geworden","ist ... geworden","wird ... worden"],a:0,ex:"The perfect passive uses 'sein' + Partizip II + 'worden' (not 'geworden')."},
      {q:"Fill the gap: 'Als ich ankam, ___ das Essen schon serviert worden.'",opts:["war","hatte","wurde","ist"],a:0,ex:"The past perfect passive is 'war' + Partizip II + 'worden': it happened before my arrival."},
      {q:"Fill the gap: 'Das Problem muss sofort ___.'",opts:["gelöst werden","gelöst worden","lösen werden","gelöst wird"],a:0,ex:"With a modal verb, the passive infinitive 'Partizip II + werden' goes to the end."}
    ]},
    {t:"Reading: an official notice",s:"Reading",qs:[
      {q:"'Sehr geehrte Mieterinnen und Mieter, am Montag wird das Wasser von 8 bis 12 Uhr abgestellt.' When is there no water?",opts:["Monday, 8 to 12","all day Monday","every morning","Monday afternoon"],a:0,ex:"'Wird abgestellt' (is being turned off) applies to Monday from 8 to 12 o'clock only."},
      {q:"'Das Formular ist bereits ausgefüllt und unterschrieben. Es muss nur noch eingereicht werden.' What still needs to be done?",opts:["hand it in","fill it in","sign it","print it"],a:0,ex:"The Zustandspassiv shows filling in and signing are done; 'muss eingereicht werden' is still to do."},
      {q:"An email says: 'Hey, hab deine Mail gekriegt, passt schon!' What register is it?",opts:["colloquial","formal business","legal","academic"],a:0,ex:"'Hey', the dropped 'e' in 'hab', 'gekriegt' and 'passt schon' are all typical of casual speech."}
    ]},
    {t:"Listening: announcements",s:"Listening",qs:[
      {q:"Listen. What is happening to the train to Hamburg?",say:"Der Zug nach Hamburg wird heute über Hannover umgeleitet.",opts:["It is being diverted via Hannover.","It has been cancelled today.","It is an hour late.","It now leaves from Hannover."],a:0,ex:"'Wird umgeleitet' is passive for 'is being diverted'; 'über Hannover' means via Hannover."},
      {q:"Listen. What is the situation of the road?",say:"Die Straße ist seit gestern gesperrt.",opts:["It has been closed since yesterday.","It is being repaired today.","It was reopened yesterday.","It will be closed tomorrow."],a:0,ex:"'Ist gesperrt' is a Zustandspassiv: the road is in a closed state, and 'seit gestern' gives the start."},
      {q:"Listen. When had the building been renovated?",say:"Das Gebäude war bereits 1990 renoviert worden.",opts:["already in 1990","only in 2019","next year","in 1919"],a:0,ex:"'War ... renoviert worden' is the past perfect passive; 'bereits 1990' means already in 1990."}
    ]},
    {t:"Switching register",s:"Speaking",qs:[
      {q:"Your boss asks about the report. Which reply fits the register?",opts:["Der Bericht ist fertig und wurde Ihnen geschickt.","Alles easy, der Bericht ist schon bei dir, Chef.","Jo, hab dir den Bericht schon rübergeschickt.","Klar, Bericht ist fertig, check mal deine Mails."],a:0,ex:"With a boss you use 'Sie'/'Ihnen' and neutral words; the others are casual and use 'du'."},
      {q:"A friend asks: 'Hast du das Paket gekriegt?' Which reply sounds natural?",opts:["Ja, hab's gestern gekriegt, danke!","Ja, ich bestätige hiermit den Erhalt.","Ja, es wurde mir ordnungsgemäß zugestellt.","Ja, ich habe es dankend erhalten."],a:0,ex:"Between friends you match the casual register; the other replies sound like an official letter."},
      {q:"A journalist asks why the road is closed. What do you say?",opts:["Die Straße wird gerade saniert.","Die Straße hat gerade saniert.","Die Straße wird gerade sanieren.","Die Straße sind gerade saniert."],a:0,ex:"The road is being renovated by someone, so you need the passive: wird + Partizip II 'saniert'."}
    ]},
    {t:"Writing a process",s:"Writing",qs:[
      {q:"Bread recipe: 'Zuerst ___ das Mehl mit Wasser gemischt.'",opts:["wird","werden","ist","hat"],a:0,ex:"Process descriptions use the Vorgangspassiv; 'das Mehl' is singular, so 'wird'."},
      {q:"Fill the gap: 'Dann werden die Brote in den Ofen ___.'",opts:["geschoben","schieben","geschiebt","schob"],a:0,ex:"The passive needs the Partizip II; 'schieben' is a strong verb, so it is 'geschoben'."},
      {q:"Which sentence with 'sich lassen' is correct?",opts:["Das Problem lässt sich leicht lösen.","Das Problem lässt leicht lösen.","Das Problem lässt sich leicht gelöst.","Das Problem sich lässt leicht lösen."],a:0,ex:"'Sich lassen' + infinitive means 'can be done': it needs 'sich' and the plain infinitive 'lösen'."}
    ]},
    {t:"Formal letters & register",s:"Culture",qs:[
      {q:"How do you open a formal letter when you don't know the recipient's name?",opts:["Sehr geehrte Damen und Herren,","Liebe Damen und Herren,","Hallo zusammen,","Werte Leute,"],a:0,ex:"'Sehr geehrte Damen und Herren' is the standard formal opening for an unknown recipient."},
      {q:"What is the standard closing of a formal business letter?",opts:["Mit freundlichen Grüßen","Mit lieben Grüßen","Viele Grüße an alle","Tschüss und danke"],a:0,ex:"'Mit freundlichen Grüßen' is the neutral, formal sign-off; 'liebe Grüße' is for friends."},
      {q:"Why do official German texts often use the passive or 'man'?",opts:["to focus on the action, not the doer","because passive is always shorter","because a law requires it","to make the text sound casual"],a:0,ex:"Rules and notices care about what is done, not who does it, so the agent is left out."}
    ]},
    {t:"Passive & register review",s:"Review",qs:[
      {q:"What does 'Das lässt sich lösen' mean?",opts:["That can be solved.","That lets itself go.","That must be solved.","That was solved."],a:0,ex:"'Sich lassen' + infinitive is a passive alternative expressing possibility: can be done."},
      {q:"What does 'Man sagt, dass er reich ist' mean?",opts:["It is said that he is rich.","He says that he is rich.","One must say he is rich.","He was told he is rich."],a:0,ex:"'Man sagt' has no specific speaker; it is like the passive 'it is said' in English."},
      {q:"Which sentence is in the Zustandspassiv?",opts:["Die Tür ist geschlossen.","Die Tür wird geschlossen.","Die Tür wurde geschlossen.","Die Tür muss geschlossen werden."],a:0,ex:"Only 'ist geschlossen' (sein + Partizip II) describes a state; the others describe a process."}
    ]},
    {t:"Challenge: tricky passives",s:"Challenge",qs:[
      {q:"Which passive sentence with 'helfen' is correct?",opts:["Mir wurde sofort geholfen.","Ich wurde sofort geholfen.","Mich wurde sofort geholfen.","Mir wurde sofort helfen."],a:0,ex:"'Helfen' takes the dative, and the dative stays in the passive: 'mir wurde geholfen' has no subject."},
      {q:"Modal + passive in the past: which sentence is correct?",opts:["Die Rechnung hätte längst bezahlt werden müssen.","Die Rechnung hätte längst bezahlt müssen werden.","Die Rechnung hätte längst bezahlen werden müssen.","Die Rechnung hätte längst bezahlt worden müssen."],a:0,ex:"Modal + passive in the past: hätte ... Partizip II + werden + müssen (double infinitive at the end)."},
      {q:"A sign says: 'Hier wird nicht geraucht.' What does it mean?",opts:["No smoking here (a rule).","Smoke is not produced here.","Nothing is being cooked here.","Smoking was banned long ago."],a:0,ex:"The impersonal passive without a subject is often used to state a rule firmly."}
    ]}
  ],
  // Module 3: Complex Connectors & Structure
  [
    {t:"Connector meanings",s:"Vocabulary",qs:[
      {q:"What does 'folglich' mean?",opts:["consequently","nevertheless","meanwhile","otherwise"],a:0,ex:"'Folglich' comes from 'folgen' (to follow): it introduces what follows as a result."},
      {q:"What does 'dennoch' mean?",opts:["nevertheless","therefore","moreover","for example"],a:0,ex:"'Dennoch' is a formal synonym of 'trotzdem': something happens despite what was said."},
      {q:"What does 'indem' express?",opts:["the method (by doing)","the result (so that)","a concession (although)","a contrast (whereas)"],a:0,ex:"'Indem' explains how something is achieved: 'Er lernt, indem er liest' = by reading."}
    ]},
    {t:"Two-part connectors",s:"Vocabulary",qs:[
      {q:"How do you say 'both ... and' in German?",opts:["sowohl ... als auch","entweder ... oder","weder ... noch","je ... desto"],a:0,ex:"'Sowohl ... als auch' links two items that both apply: sowohl Deutsch als auch Französisch."},
      {q:"What does 'weder ... noch' mean?",opts:["neither ... nor","either ... or","both ... and","not only ... but also"],a:0,ex:"'Weder ... noch' negates both items, like English 'neither ... nor'."},
      {q:"Which connector expresses a contrast between two facts?",opts:["wohingegen","folglich","sodass","indem"],a:0,ex:"'Wohingegen' means 'whereas'; 'folglich' and 'sodass' give results and 'indem' gives a method."}
    ]},
    {t:"Stress in connectors",s:"Pronunciation",qs:[
      {q:"Listen. How is the 'ch' at the end of 'folglich' pronounced?",say:"folglich",opts:["soft, like the 'h' in 'huge'","hard, like 'k'","like 'ch' in Scottish 'loch'","like 'sh' in 'show'"],a:0,ex:"After 'i' the 'ch' is the soft ich-Laut, made at the front of the mouth, close to 'h' in 'huge'."},
      {q:"Listen. Which syllable is stressed in 'sodass'?",say:"sodass",opts:["-dass","so-","both equally","neither"],a:0,ex:"In 'sodass' the stress falls on the second syllable: so-DASS."},
      {q:"Listen. Which syllable is stressed in 'wohingegen'?",say:"wohingegen",opts:["-ge-","wo-","-hin-","-gen"],a:0,ex:"'Wohingegen' is stressed on the third syllable: wohin-GE-gen, like 'dagegen'."}
    ]},
    {t:"Je ... desto ...",s:"Grammar",qs:[
      {q:"Fill the gap: 'Je mehr ich übe, ___ besser werde ich.'",opts:["desto","sodass","als","dann"],a:0,ex:"'Je + comparative' is completed by 'desto (or umso) + comparative'."},
      {q:"Which 'je ... desto' sentence has the correct word order?",opts:["Je früher wir anfangen, desto schneller sind wir fertig.","Je früher fangen wir an, desto schneller sind wir fertig.","Je früher wir anfangen, desto wir sind schneller fertig.","Je früher wir anfangen, desto schneller wir sind fertig."],a:0,ex:"The 'je' clause has the verb at the end; after 'desto + comparative' the verb comes next."},
      {q:"Fill the gaps: 'Sie spricht ___ Deutsch ___ Französisch.'",opts:["sowohl ... als auch","sowohl ... oder","entweder ... sondern","weder ... als auch"],a:0,ex:"The fixed pairs are 'sowohl ... als auch', 'entweder ... oder' and 'weder ... noch'."}
    ]},
    {t:"indem, sodass & dennoch",s:"Grammar",qs:[
      {q:"Fill the gap: 'Er verbesserte sein Deutsch, ___ er täglich Podcasts hörte.'",opts:["indem","sodass","dennoch","folglich"],a:0,ex:"Listening to podcasts is the method he used, so 'indem' (by doing) fits; the verb goes to the end."},
      {q:"Fill the gap: 'Es regnete stark, ___ das Spiel abgesagt wurde.'",opts:["sodass","indem","dennoch","sowohl"],a:0,ex:"The cancellation is the result of the rain, and 'sodass' introduces a result clause."},
      {q:"Fill the gap: 'Es war sehr kalt. ___ gingen wir spazieren.'",opts:["Dennoch","Indem","Sodass","Wohingegen"],a:0,ex:"'Dennoch' is an adverb in position 1, followed by the verb; the others are subordinating conjunctions."}
    ]},
    {t:"Reading: a report paragraph",s:"Reading",qs:[
      {q:"'Die Firma hat nicht nur ihren Umsatz gesteigert, sondern auch neue Mitarbeiter eingestellt.' What is true?",opts:["Both revenue and staff grew.","Only the revenue grew.","Staff were laid off.","Revenue fell, staff grew."],a:0,ex:"'Nicht nur ... sondern auch' means both things happened: higher revenue and new employees."},
      {q:"'Anna lernt am liebsten morgens, wohingegen ihr Bruder abends am produktivsten ist.' What is true?",opts:["They prefer different times of day.","Both prefer studying in the morning.","Her brother does not study at all.","Anna studies best at night."],a:0,ex:"'Wohingegen' contrasts the two: Anna prefers mornings, her brother evenings."},
      {q:"'Die Preise sind gestiegen. Dennoch kaufen die Kunden weiterhin viel.' What happened?",opts:["Customers keep buying despite higher prices.","Customers stopped buying because of prices.","Prices fell, so customers bought more.","Customers bought less than before."],a:0,ex:"'Dennoch' (nevertheless) shows that buying continues in spite of the price rise."}
    ]},
    {t:"Listening: linked ideas",s:"Listening",qs:[
      {q:"Listen. How do the speaker's feelings about Berlin change over time?",say:"Je länger ich in Berlin wohne, desto mehr gefällt mir die Stadt.",opts:["They like it more and more.","They like it less and less.","Their opinion stays the same.","They want to leave soon."],a:0,ex:"'Je länger ..., desto mehr ...' links two increases: the longer they live there, the more they like it."},
      {q:"Listen. Which options does the speaker give?",say:"Entweder wir nehmen den Zug, oder wir bleiben zu Hause.",opts:["the train or staying home","the train and the car","the bus or the train","walking and staying home"],a:0,ex:"'Entweder ... oder' offers two alternatives: taking the train or staying at home."},
      {q:"Listen. How did he pass the exam?",say:"Er hat die Prüfung bestanden, indem er jeden Tag gelernt hat.",opts:["by studying every day","by pure luck","with a private tutor","by studying at night"],a:0,ex:"'Indem' introduces the method: he passed by studying every day."}
    ]},
    {t:"Explaining cause and effect",s:"Speaking",qs:[
      {q:"In a presentation you explain a consequence. Which sentence is right?",opts:["Die Temperaturen steigen, folglich schmilzt das Eis.","Die Temperaturen steigen, folglich das Eis schmilzt.","Die Temperaturen steigen, indem das Eis schmilzt.","Die Temperaturen steigen, dennoch schmilzt das Eis."],a:0,ex:"'Folglich' gives a result and, as an adverb in position 1, is followed by the verb."},
      {q:"A friend can't decide between Spanish and Italian. You think they should learn both. What do you say?",opts:["Lern doch sowohl Spanisch als auch Italienisch!","Lern doch weder Spanisch noch Italienisch!","Lern doch entweder Spanisch oder Italienisch!","Lern doch nicht Spanisch, sondern Italienisch!"],a:0,ex:"'Sowohl ... als auch' recommends both; the other pairs mean neither, one of them, or only Italian."},
      {q:"You explain how you save money. What do you say?",opts:["Ich spare Geld, indem ich mit dem Rad fahre.","Ich spare Geld, sodass ich mit dem Rad fahre.","Ich spare Geld, indem fahre ich mit dem Rad.","Ich spare Geld, dennoch ich fahre mit dem Rad."],a:0,ex:"Cycling is the method, so 'indem' fits, and as a subordinating conjunction it sends the verb to the end."}
    ]},
    {t:"Nominal style & structure",s:"Writing",qs:[
      {q:"Turn 'Wenn man regelmäßig lernt, ...' into nominal style.",opts:["Durch regelmäßiges Lernen ...","Durch regelmäßig lernen ...","Durch regelmäßige Lernen ...","Durch regelmäßigem Lernen ..."],a:0,ex:"'Das Lernen' is neuter; after 'durch' (accusative) without an article the adjective ending is -es."},
      {q:"Which noun belongs to the verb 'entscheiden'?",opts:["die Entscheidung","die Entscheidheit","das Entschied","die Entscheidnis"],a:0,ex:"Many verbs form feminine nouns with -ung: entscheiden -> die Entscheidung, entwickeln -> die Entwicklung."},
      {q:"Which sentence is correctly written?",opts:["Nicht nur der Preis, sondern auch die Qualität überzeugt.","Nicht nur der Preis, aber auch die Qualität überzeugt.","Nicht nur der Preis, sondern die auch Qualität überzeugt.","Nicht der Preis nur, sondern auch die Qualität überzeugt."],a:0,ex:"The fixed pair is 'nicht nur ... sondern auch', with 'auch' placed directly after 'sondern'."}
    ]},
    {t:"How German essays are built",s:"Culture",qs:[
      {q:"Which phrase typically opens the conclusion of a formal German text?",opts:["Zusammenfassend lässt sich sagen, dass ...","Also, kurz und knapp gesagt ...","Übrigens finde ich auch, dass ...","Zuerst möchte ich sagen, dass ..."],a:0,ex:"'Zusammenfassend lässt sich sagen' (in summary) is the classic formal signal for a conclusion."},
      {q:"What is an 'Erörterung' in German schools?",opts:["an essay weighing pros and cons","an analysis of a classic poem","a short creative story","a formal letter of complaint"],a:0,ex:"In an Erörterung pupils discuss a question by weighing arguments before reaching a judgement."},
      {q:"What is the classic order of parts in a German essay?",opts:["Einleitung – Hauptteil – Schluss","Einleitung – Schluss – Hauptteil","Hauptteil – Einleitung – Schluss","Schluss – Hauptteil – Einleitung"],a:0,ex:"German schools teach introduction (Einleitung), main part (Hauptteil) and conclusion (Schluss)."}
    ]},
    {t:"Connectors review",s:"Review",qs:[
      {q:"What does 'sodass' introduce?",opts:["a result","a method","a contrast","a condition"],a:0,ex:"'Sodass' (so that) introduces the result of the main clause: 'Es regnete, sodass ...'."},
      {q:"Fill the gap: 'Je ___ das Wetter, desto mehr Leute gehen schwimmen.'",opts:["wärmer","warm","am wärmsten","wärmste"],a:0,ex:"'Je' must be followed by a comparative: je wärmer, desto mehr."},
      {q:"Which connector does NOT express a consequence?",opts:["wohingegen","folglich","sodass","deshalb"],a:0,ex:"'Wohingegen' expresses contrast; 'folglich', 'sodass' and 'deshalb' all introduce results."}
    ]},
    {t:"Challenge: connector traps",s:"Challenge",qs:[
      {q:"Which sentence with 'dennoch' is correct?",opts:["Es war kalt, dennoch gingen wir spazieren.","Es war kalt, dennoch wir gingen spazieren.","Es war kalt, dennoch spazieren wir gingen.","Es war kalt, wir dennoch gingen spazieren."],a:0,ex:"'Dennoch' is an adverb, not a conjunction: when it starts the clause, the verb must come next."},
      {q:"In 'Er spart jeden Cent, während sein Bruder alles ausgibt', what does 'während' express?",opts:["a contrast (whereas)","a cause (because)","a result (so that)","a condition (if)"],a:0,ex:"Besides 'while' (time), 'während' can mean 'whereas', contrasting two people's behaviour."},
      {q:"Complete: 'Je mehr Menschen das Angebot nutzen, desto ___.'",opts:["günstiger wird es","wird es günstiger","es wird günstiger","günstiger es wird"],a:0,ex:"'Desto' and the comparative stay together in position 1, then the verb follows: desto günstiger wird es."}
    ]}
  ],
  // Module 4: News Analysis & Abstract Ideas
  [
    {t:"News vocabulary",s:"Vocabulary",qs:[
      {q:"What does 'die Schlagzeile' mean?",opts:["the headline","the article","the editor","the subscription"],a:0,ex:"'Die Schlagzeile' is the large title line that 'hits' the reader at the top of an article."},
      {q:"What does 'die Berichterstattung' mean?",opts:["the coverage","the reporter","the correction","the press release"],a:0,ex:"From 'Bericht erstatten' (to report): it means the way the media cover a topic."},
      {q:"What does 'voreingenommen' mean?",opts:["biased","prepared","informed","neutral"],a:0,ex:"'Voreingenommen' means having an opinion before looking at the facts, i.e. biased."}
    ]},
    {t:"Abstract nouns & trends",s:"Vocabulary",qs:[
      {q:"Which is the abstract noun formed from 'gerecht' (fair, just)?",opts:["die Gerechtigkeit","die Gerechtheit","die Gerechtung","die Gerechtnis"],a:0,ex:"Adjectives ending in -t often take -igkeit: gerecht -> Gerechtigkeit, like nachhaltig -> Nachhaltigkeit."},
      {q:"Which noun is the opposite of 'der Anstieg' (the rise)?",opts:["der Rückgang","der Aufschwung","der Zuwachs","die Zunahme"],a:0,ex:"'Der Rückgang' is a decline; 'Aufschwung', 'Zuwachs' and 'Zunahme' all describe growth."},
      {q:"What does 'die Auswirkung' mean?",opts:["the effect / impact","the exit","the selection","the explanation"],a:0,ex:"'Sich auswirken auf' means to have an effect on, so 'die Auswirkung' is the effect or impact."}
    ]},
    {t:"Stress in abstract nouns",s:"Pronunciation",qs:[
      {q:"Listen. Which syllable is stressed in 'Nachhaltigkeit'?",say:"die Nachhaltigkeit",opts:["Nach-","-hal-","-tig-","-keit"],a:0,ex:"'Nachhaltig' stresses its prefix 'nach-', and the suffix -keit does not move the stress."},
      {q:"Listen. Which syllable is stressed in 'Verantwortung'?",say:"die Verantwortung",opts:["-ant-","Ver-","-wor-","-tung"],a:0,ex:"The prefix 'ver-' is never stressed; the stress falls on '-ant-': ver-ANT-wor-tung."},
      {q:"Listen. How is the 'ü' in 'Rückgang' pronounced?",say:"der Rückgang",opts:["a short 'i' said with rounded lips","like 'oo' in English 'food'","like 'u' in English 'cup'","like 'ee' in English 'see'"],a:0,ex:"Before a double consonant like 'ck', 'ü' is short: say a short 'i' and round your lips."}
    ]},
    {t:"Citing sources: laut & zufolge",s:"Grammar",qs:[
      {q:"Fill the gap: 'Laut ___ Studie steigt die Zahl der Pendler.'",opts:["der","die","den","dem"],a:0,ex:"'Laut' is followed by the dative (or genitive); for feminine 'Studie' both give 'der'."},
      {q:"Fill the gap: 'Einem Bericht ___ ist die Arbeitslosigkeit gesunken.'",opts:["zufolge","folglich","zuliebe","entlang"],a:0,ex:"'Zufolge' (according to) follows its dative noun: einem Bericht zufolge."},
      {q:"Which sentence with 'zufolge' is correct?",opts:["Den Angaben zufolge gab es keine Verletzten.","Zufolge den Angaben gab es keine Verletzten.","Die Angaben zufolge gab es keine Verletzten.","Den Angaben zufolge es gab keine Verletzten."],a:0,ex:"With the dative, 'zufolge' comes after the noun; the whole phrase is position 1, so the verb follows."}
    ]},
    {t:"Nominal style in news",s:"Grammar",qs:[
      {q:"Headline: 'Anstieg der Mieten'. What does it say in a full sentence?",opts:["Die Mieten steigen.","Die Mieten sinken.","Man mietet mehr.","Die Mieter steigen ein."],a:0,ex:"Nominal headlines turn verbs into nouns: 'der Anstieg der Mieten' = 'die Mieten steigen'."},
      {q:"Turn 'Die Regierung entscheidet.' into nominal style.",opts:["die Entscheidung der Regierung","die Entscheidung von der Regierungs","der Regierung Entscheiden","die Entscheidung des Regierung"],a:0,ex:"The verb becomes a noun and the subject becomes a genitive: die Entscheidung der Regierung."},
      {q:"Fill the gap: 'Wegen der Erhöhung ___ Preise sind viele Kunden unzufrieden.'",opts:["der","den","die","dem"],a:0,ex:"Nominal style chains genitives; the genitive plural article is 'der': die Erhöhung der Preise."}
    ]},
    {t:"Reading: news items",s:"Reading",qs:[
      {q:"'Laut Statistischem Bundesamt ist die Zahl der Geburten im Jahr 2023 um rund sechs Prozent zurückgegangen.' What does the text report?",opts:["a fall in births","a rise in births","no change in births","a rise in deaths"],a:0,ex:"'Zurückgehen' means to decline, so the number of births fell by about six percent."},
      {q:"'Kommentar: Die Regierung tut viel zu wenig für den Klimaschutz.' Is this a fact or an opinion?",opts:["an opinion","a neutral fact","a study's result","an official statistic"],a:0,ex:"It is labelled 'Kommentar' and uses the judgement 'viel zu wenig', so it expresses an opinion."},
      {q:"'Das Unternehmen trägt nach eigenen Angaben keine Verantwortung für den Unfall.' Who says the company is not responsible?",opts:["the company itself","the local police","a court of law","the journalists"],a:0,ex:"'Nach eigenen Angaben' means 'according to its own statements', so the claim comes from the company."}
    ]},
    {t:"Listening: news headlines",s:"Listening",qs:[
      {q:"Listen. What is the source of the information?",say:"Einer aktuellen Umfrage zufolge halten siebzig Prozent der Befragten Nachhaltigkeit für wichtig.",opts:["a recent survey","a government report","an expert interview","a court ruling"],a:0,ex:"'Einer aktuellen Umfrage zufolge' names a recent survey as the source."},
      {q:"Listen. What happened to unemployment?",say:"Die Arbeitslosigkeit ist im Mai leicht zurückgegangen.",opts:["It fell slightly in May.","It rose sharply in May.","It stayed the same in May.","It fell sharply in March."],a:0,ex:"'Leicht zurückgegangen' means it decreased slightly, and the month mentioned is May."},
      {q:"Listen. What do critics accuse the newspaper of?",say:"Kritiker werfen der Zeitung vor, einseitig zu berichten.",opts:["one-sided reporting","reporting too late","spelling mistakes","too many adverts"],a:0,ex:"'Jemandem etwas vorwerfen' means to accuse; 'einseitig berichten' is to report one-sidedly."}
    ]},
    {t:"Discussing the news",s:"Speaking",qs:[
      {q:"You report what a newspaper says without claiming it is true. What do you say?",opts:["Einem Bericht zufolge soll die Steuer steigen.","Es steht außer Frage, dass die Steuer steigt.","Ich weiß ganz sicher, dass die Steuer steigt.","Fakt ist, dass die Steuer bald steigen wird."],a:0,ex:"'Zufolge' names the source, and 'soll' signals reported information, keeping a distance from the claim."},
      {q:"You think an article is not neutral. What do you say?",opts:["Ich finde den Artikel ziemlich voreingenommen.","Ich finde den Artikel ziemlich vorgenommen.","Ich finde den Artikel ziemlich angenommen.","Ich finde den Artikel ziemlich vorgestellt."],a:0,ex:"'Voreingenommen' means biased; 'vorgenommen', 'angenommen' and 'vorgestellt' are unrelated participles."},
      {q:"Summing up an article: 'Im Kern geht es in dem Artikel ___, dass die Mieten zu hoch sind.'",opts:["darum","davon","darüber","dafür"],a:0,ex:"The fixed expression is 'es geht um etwas', so the pronominal adverb is 'darum'."}
    ]},
    {t:"Writing a summary",s:"Writing",qs:[
      {q:"Fill the gap: 'Der Artikel befasst sich ___ den Auswirkungen des Klimawandels.'",opts:["mit","über","von","an"],a:0,ex:"'Sich befassen' always takes 'mit' + dative: sich mit einem Thema befassen."},
      {q:"Reporting speech: 'Der Minister sagte, er ___ mit dem Ergebnis zufrieden.'",opts:["sei","seien","sein","wäre sein"],a:0,ex:"News reports use Konjunktiv I for indirect speech; for 'er' the form of 'sein' is 'sei'."},
      {q:"Which sentence is the most suitable start for a written summary?",opts:["Der Text behandelt das Thema ...","In dem Text geht's halt um ...","Also, der Text, der ist über ...","Der Text redet so über ..."],a:0,ex:"'Behandeln' is the neutral written verb; 'geht's halt', 'der ist über' and 'redet so' are spoken style."}
    ]},
    {t:"German media landscape",s:"Culture",qs:[
      {q:"What is the 'Tagesschau'?",opts:["the main evening TV news on ARD","a daily tabloid newspaper","a radio quiz show","a weekly news magazine"],a:0,ex:"The Tagesschau has been ARD's main news programme since 1952; its 8 pm edition is a national ritual."},
      {q:"What is 'Bild' known as?",opts:["Germany's biggest tabloid","a public TV channel","a national news agency","a science magazine"],a:0,ex:"'Bild' is a tabloid with big headlines and short texts, known for sensational reporting."},
      {q:"How are the public broadcasters ARD and ZDF mainly financed?",opts:["by the Rundfunkbeitrag fee","by advertising only","by private donations","by pay-per-view"],a:0,ex:"Households pay a compulsory broadcasting fee, the Rundfunkbeitrag, which funds public media."}
    ]},
    {t:"News review",s:"Review",qs:[
      {q:"What does 'die Verantwortung' mean?",opts:["responsibility","the answer","opposition","the effect"],a:0,ex:"'Verantwortung' contains 'Antwort': being responsible means having to answer for something."},
      {q:"Fill the gap: 'Es gab einen deutlichen ___ der Preise.'",opts:["Anstieg","Aufstieg","Einstieg","Umstieg"],a:0,ex:"Prices have an 'Anstieg' (rise); 'Aufstieg' is a promotion or climb, 'Einstieg' an entry, 'Umstieg' a change."},
      {q:"Which sentence is an opinion rather than a fact?",opts:["Diese Reform ist ein großer Fehler.","Die Reform tritt im Januar in Kraft.","Der Bundestag hat die Reform beschlossen.","Die Reform betrifft zwei Millionen Menschen."],a:0,ex:"'Ein großer Fehler' is an evaluation; the other sentences state checkable facts."}
    ]},
    {t:"Challenge: news language",s:"Challenge",qs:[
      {q:"Headline: 'Rückgang der Arbeitslosigkeit trotz Krise'. What does it mean?",opts:["Die Arbeitslosigkeit geht trotz der Krise zurück.","Die Arbeitslosigkeit steigt trotz der Krise.","Wegen der Krise geht die Arbeitslosigkeit zurück.","Die Krise geht trotz der Arbeitslosigkeit zurück."],a:0,ex:"'Rückgang' = zurückgehen, and 'trotz' means despite: unemployment falls even though there is a crisis."},
      {q:"Fill the gap: 'Den Behörden ___ wurde niemand verletzt.'",opts:["zufolge","wegen","trotz","statt"],a:0,ex:"'Den Behörden zufolge' = according to the authorities; 'wegen', 'trotz' and 'statt' make no sense here."},
      {q:"Which adjective describes reporting that shows only one side?",opts:["einseitig","ausgewogen","sachlich","neutral"],a:0,ex:"'Einseitig' means one-sided; 'ausgewogen' (balanced), 'sachlich' and 'neutral' are the opposite."}
    ]}
  ],
  // Module 5: Negotiation, Presentation & Review
  [
    {t:"Negotiation key words",s:"Vocabulary",qs:[
      {q:"In a negotiation: 'Wir kommen Ihnen beim Preis entgegen.' What does it mean?",opts:["We'll meet you halfway on the price.","We'll raise the price for you.","We'll come to your office about it.","We won't discuss the price."],a:0,ex:"'Jemandem entgegenkommen' means making a concession to the other side."},
      {q:"What does 'einen Kompromiss finden' mean?",opts:["to find a compromise","to break an agreement","to make a complaint","to win an argument"],a:0,ex:"A Kompromiss is a solution where each side gives up part of its demands."},
      {q:"In a presentation, what does 'abschließend' mean?",opts:["finally","to begin with","for example","meanwhile"],a:0,ex:"'Abschließend' comes from 'abschließen' (to conclude) and introduces the final point."}
    ]},
    {t:"Signposts & conditions",s:"Vocabulary",qs:[
      {q:"Which signpost opens the first point of a presentation?",opts:["Zunächst ...","Im nächsten Schritt ...","Abschließend ...","Damit komme ich zum Schluss."],a:0,ex:"'Zunächst' means 'first of all'; the others mark the next step or the end."},
      {q:"What does 'unter der Bedingung, dass ...' mean?",opts:["on condition that ...","unless ...","even though ...","as a result of ..."],a:0,ex:"'Die Bedingung' is the condition: you only agree if that condition is met."},
      {q:"What does 'Wie bereits erwähnt ...' mean?",opts:["As already mentioned ...","As expected ...","As soon as possible ...","As you can see ..."],a:0,ex:"'Erwähnen' means to mention and 'bereits' means already: you refer back to an earlier point."}
    ]},
    {t:"Stress in presentation words",s:"Pronunciation",qs:[
      {q:"Listen. Which syllable is stressed in 'Kompromiss'?",say:"der Kompromiss",opts:["-miss","Kom-","-pro-","all equally"],a:0,ex:"This Latin loanword stresses its final syllable: Kompro-MISS."},
      {q:"Listen. Which syllable is stressed in 'Präsentation'?",say:"die Präsentation",opts:["-tion","Prä-","-sen-","-ta-"],a:0,ex:"Nouns ending in -tion always stress that ending, pronounced 'tsjohn': Präsenta-TION."},
      {q:"Listen. Which syllable is stressed in 'entgegenkommen'?",say:"entgegenkommen",opts:["-ge-","ent-","-gen","-kom-"],a:0,ex:"The separable prefix 'entgegen' carries the stress on its middle syllable: ent-GE-gen-kommen."}
    ]},
    {t:"Proposals and agreement",s:"Grammar",qs:[
      {q:"Which form makes this proposal more tentative: 'Wir ___ uns auf zehn Prozent einigen.'?",opts:["könnten","können","konnten","gekonnt"],a:0,ex:"Konjunktiv II 'könnten' makes a suggestion sound softer and more open than 'können'."},
      {q:"Fill the gap: 'Ich schlage vor, dass wir den Termin ___.'",opts:["verschieben","verschoben","zu verschieben","verschiebt"],a:0,ex:"After 'dass' the conjugated verb goes to the end and agrees with 'wir': verschieben."},
      {q:"Fill the gap: 'Wir haben uns ___ einen Preis geeinigt.'",opts:["auf","über","mit","an"],a:0,ex:"'Sich auf etwas einigen' (accusative) means to agree on something."}
    ]},
    {t:"Conditions & soft feedback",s:"Grammar",qs:[
      {q:"Fill the gap: 'Wir stimmen zu, unter der Bedingung, dass Sie früher ___.'",opts:["liefern","liefern Sie","geliefert","zu liefern"],a:0,ex:"The 'dass' clause sends the conjugated verb 'liefern' to the end."},
      {q:"Which verb gives this feedback most gently: 'Die Einleitung ___ etwas kürzer sein.'?",opts:["könnte","muss","soll","wird"],a:0,ex:"Konjunktiv II 'könnte' turns a criticism into a suggestion; 'muss' and 'soll' sound like orders."},
      {q:"Fill the gap: 'Wie Sie ___ Grafik entnehmen können, steigt der Umsatz.'",opts:["der","die","den","das"],a:0,ex:"'Etwas einer Sache entnehmen' takes the dative; 'die Grafik' becomes 'der Grafik'."}
    ]},
    {t:"Reading: a proposal email",s:"Reading",qs:[
      {q:"'Leider können wir den Termin am 15. nicht halten. Ich schlage vor, die Abgabe auf den 30. zu verschieben. Im Gegenzug kommen wir Ihnen beim Preis entgegen.' What is proposed?",opts:["a later deadline and a lower price","the same deadline and a lower price","a later deadline and a higher price","cancelling the whole project"],a:0,ex:"The deadline moves to the 30th, and 'im Gegenzug ... entgegenkommen' offers a concession on price."},
      {q:"'Unser Angebot gilt nur unter der Bedingung, dass die Zahlung innerhalb von 14 Tagen erfolgt.' What is the condition?",opts:["payment within 14 days","delivery within 14 days","a 14 percent discount","a free 14-day trial"],a:0,ex:"'Die Zahlung erfolgt' means the payment is made; it must happen within 14 days."},
      {q:"Peer feedback: 'Dein Vortrag war gut strukturiert. Die Folien könnten allerdings weniger Text haben.' What is suggested?",opts:["less text on the slides","more slides overall","a clearer structure","a longer talk"],a:0,ex:"The structure is praised; 'könnten ... weniger Text haben' gently suggests shorter slide texts."}
    ]},
    {t:"Listening: talks & offers",s:"Listening",qs:[
      {q:"Listen. Which part of a presentation is this?",say:"Damit komme ich zum Schluss und bedanke mich für Ihre Aufmerksamkeit.",opts:["the end","the introduction","the middle part","the question round"],a:0,ex:"'Damit komme ich zum Schluss' and thanking the audience mark the end of a talk."},
      {q:"Listen. What does the graph show?",say:"Wie Sie der Grafik entnehmen können, ist der Umsatz um zehn Prozent gestiegen.",opts:["revenue up by 10 percent","revenue down by 10 percent","costs up by 10 percent","revenue up by 20 percent"],a:0,ex:"'Der Umsatz' is revenue, and 'um zehn Prozent gestiegen' means it rose by ten percent."},
      {q:"Listen. Under what condition will they make a concession?",say:"Wir könnten Ihnen entgegenkommen, wenn Sie mindestens hundert Stück bestellen.",opts:["if you order at least 100","if you pay in advance","if you order today","if you order fewer than 100"],a:0,ex:"'Mindestens hundert Stück' means at least one hundred items; that is the condition."}
    ]},
    {t:"Negotiating & presenting",s:"Speaking",qs:[
      {q:"Your partner wants 20% off; you can offer 10%. How do you look for a compromise?",opts:["Wie wäre es, wenn wir uns bei zehn Prozent treffen?","Zwanzig Prozent sind für uns kein Problem.","Wir geben grundsätzlich überhaupt keinen Rabatt.","Das ist mir eigentlich ziemlich egal."],a:0,ex:"'Wie wäre es, wenn ...' makes a soft counter-offer that leaves room for agreement."},
      {q:"Give a peer constructive feedback on their talk.",opts:["Dein Einstieg war stark, aber der Schluss könnte klarer sein.","Dein Einstieg war schwach, und der Schluss war auch schlecht.","Dein Vortrag war okay, mehr kann ich dazu nicht sagen.","Dein Schluss muss sofort komplett anders werden."],a:0,ex:"Constructive feedback names a strength and gives a tip softened with Konjunktiv II ('könnte')."},
      {q:"You move on to the next point of your presentation. What do you say?",opts:["Im nächsten Schritt möchte ich auf die Kosten eingehen.","Abschließend möchte ich jetzt mit den Kosten beginnen.","Zunächst komme ich damit zum Schluss meines Vortrags.","Wie bereits erwähnt, fange ich jetzt erst einmal an."],a:0,ex:"'Im nächsten Schritt' signals a transition; 'auf etwas eingehen' means to deal with a point."}
    ]},
    {t:"Writing a proposal email",s:"Writing",qs:[
      {q:"Which proposal sentence is correctly written?",opts:["Ich schlage vor, dass wir uns nächste Woche treffen.","Ich schlage vor, dass wir treffen uns nächste Woche.","Ich schlage vor, dass uns wir nächste Woche treffen.","Ich schlage vor, das wir uns nächste Woche treffen."],a:0,ex:"The conjunction is 'dass' with double s; the subject comes first and the verb goes to the end."},
      {q:"Fill the gap: 'Wir wären bereit, Ihnen ___ Preis entgegenzukommen.'",opts:["beim","zum","vom","am"],a:0,ex:"You make a concession 'bei' a point of negotiation: beim (bei dem) Preis entgegenkommen."},
      {q:"Which spelling is correct?",opts:["Wir sind bereit, Ihnen entgegenzukommen.","Wir sind bereit, Ihnen entgegen zu kommen.","Wir sind bereit, Ihnen zu entgegenkommen.","Wir sind bereit, Ihnen entgegenkommen zu."],a:0,ex:"With separable verbs, 'zu' goes between prefix and stem and is written as one word: entgegenzukommen."}
    ]},
    {t:"Business etiquette",s:"Culture",qs:[
      {q:"In a traditional German business setting, who usually offers to switch from 'Sie' to 'du'?",opts:["the older or more senior person","the younger or junior person","whoever speaks first","nobody: it is never done"],a:0,ex:"Traditionally the senior or older person offers the 'du', so the junior person waits to be asked."},
      {q:"A business meeting starts at 10:00. Arriving at 10:15 without notice is usually seen as ...",opts:["unprofessional","perfectly normal","a sign of respect","expected"],a:0,ex:"Punctuality is highly valued in German business; if you are late you should call ahead."},
      {q:"Why do German speakers often use 'könnte' and 'würde' when giving feedback?",opts:["to sound polite and less direct","to talk about the past","to give clear orders","because it is required in writing"],a:0,ex:"Konjunktiv II turns direct criticism into a suggestion, which keeps feedback constructive."}
    ]},
    {t:"Presentation review",s:"Review",qs:[
      {q:"What does 'Ich schlage vor, dass ...' mean?",opts:["I propose that ...","I insist that ...","I doubt that ...","I regret that ..."],a:0,ex:"'Vorschlagen' means to propose or suggest; it introduces a proposal, often in a 'dass' clause."},
      {q:"When do you say 'Damit komme ich zum Schluss.'?",opts:["at the end of a talk","at the start of a talk","when you disagree","when you ask a question"],a:0,ex:"'Zum Schluss kommen' means to come to the end, so it announces the conclusion."},
      {q:"Fill the gap: 'Wie bereits ___, steigen die Kosten weiter.'",opts:["erwähnt","erwähnen","erwähnte","erwähnend"],a:0,ex:"The fixed phrase uses the Partizip II: 'wie bereits erwähnt' (as already mentioned)."}
    ]},
    {t:"Challenge: negotiation German",s:"Challenge",qs:[
      {q:"Complete correctly: 'Wir könnten uns darauf einigen, ___.'",opts:["dass jede Seite die Hälfte zahlt","dass jede Seite zahlt die Hälfte","jede Seite die Hälfte zahlt dass","dass zahlt jede Seite die Hälfte"],a:0,ex:"'Darauf' points forward to the 'dass' clause, in which the verb 'zahlt' must stand at the end."},
      {q:"Feedback: 'Das Argument ___ stärker belegt werden.'",opts:["könnte","hätte","wäre","sei"],a:0,ex:"A modal verb is needed before the passive infinitive 'belegt werden'; 'könnte' makes it a polite tip."},
      {q:"Which sentence is correct for a formal email?",opts:["Wir wären Ihnen dankbar, wenn Sie uns bis Freitag Bescheid geben könnten.","Wir wären Ihnen dankbar, wenn Sie uns bis Freitag Bescheid könnten geben.","Wir wären Ihnen dankbar, wenn Sie könnten uns bis Freitag Bescheid geben.","Wir wären Ihnen dankbar, dass Sie uns bis Freitag Bescheid geben könnten."],a:0,ex:"In the 'wenn' clause the modal 'könnten' goes last, after the infinitive; 'dankbar, wenn' is the fixed pattern."}
    ]}
  ],
  // Module 6: Konjunktiv II & Hypotheticals
  [
    {t:"Konjunktiv II forms",s:"Vocabulary",qs:[
      {q:"'Wäre' is the Konjunktiv II form of which verb?",opts:["sein","werden","haben","wissen"],a:0,ex:"'Sein' has its own Konjunktiv II: ich wäre, du wärst, er wäre (from the past 'war' + umlaut)."},
      {q:"'Hätte' is the Konjunktiv II form of which verb?",opts:["haben","halten","heißen","hängen"],a:0,ex:"'Haben' -> past 'hatte' -> Konjunktiv II 'hätte' (with umlaut): Ich hätte gern ..."},
      {q:"What does 'An deiner Stelle ...' mean?",opts:["In your place ...","On your way ...","At your house ...","In your opinion ..."],a:0,ex:"'Die Stelle' here means position; 'An deiner Stelle würde ich ...' gives advice like 'If I were you'."}
    ]},
    {t:"would, could, as if",s:"Vocabulary",qs:[
      {q:"What does 'als ob' mean?",opts:["as if","as soon as","even if","as long as"],a:0,ex:"'Als ob' introduces an unreal comparison and is followed by Konjunktiv II: als ob er krank wäre."},
      {q:"What does 'müsste' mean?",opts:["would have to","might be allowed","should have done","could easily"],a:0,ex:"'Müsste' is the Konjunktiv II of 'müssen': a hypothetical obligation, 'would have to'."},
      {q:"'Wüsste' is the Konjunktiv II form of which verb?",opts:["wissen","wünschen","waschen","werden"],a:0,ex:"'Wissen' -> past 'wusste' -> Konjunktiv II 'wüsste': Wenn ich das wüsste ..."}
    ]},
    {t:"wäre, hätte, würde",s:"Pronunciation",qs:[
      {q:"Listen. Which word do you hear?",say:"Ich wäre gern dabei.",opts:["wäre","war","Ware","wer"],a:0,ex:"'Wäre' has a long open 'ä' sound, close to 'ai' in English 'air', unlike the 'a' in 'war'."},
      {q:"Listen. Which verb form do you hear in this order?",say:"Ich hätte gern einen Tee.",opts:["hätte","hatte","Hütte","heute"],a:0,ex:"The umlaut makes the difference: 'hätte' (short ä, like 'e' in 'bed') is Konjunktiv II, 'hatte' is past."},
      {q:"Listen. How is the 'ü' in 'würde' pronounced?",say:"Ich würde gern reisen.",opts:["a short 'i' said with rounded lips","like 'oo' in English 'wood'","like 'u' in English 'fur'","like 'ee' in English 'see'"],a:0,ex:"The 'ü' in 'würde' is short: say 'i' and round your lips; without the umlaut 'wurde' is past tense."}
    ]},
    {t:"Unreal present with würde",s:"Grammar",qs:[
      {q:"Fill the gap: 'Wenn ich Zeit hätte, ___ ich mitkommen.'",opts:["würde","werde","wurde","wäre"],a:0,ex:"Most verbs form Konjunktiv II with 'würde' + infinitive; 'werde' is future and 'wurde' is past."},
      {q:"Fill the gap: 'Wenn ich du ___, würde ich das Angebot annehmen.'",opts:["wäre","bin","war","hätte"],a:0,ex:"An unreal condition needs Konjunktiv II; 'sein' uses its own form 'wäre' rather than 'würde sein'."},
      {q:"Ordering politely: 'Ich ___ gern einen Kaffee.'",opts:["hätte","hatte","habe","hätten"],a:0,ex:"'Ich hätte gern ...' is the polite way to order; 'hätten' is plural and 'hatte' is past tense."}
    ]},
    {t:"Unreal past: hätte/wäre + Partizip",s:"Grammar",qs:[
      {q:"Fill the gap: 'Wenn du angerufen ___, wäre ich gekommen.'",opts:["hättest","wärst","würdest","hattest"],a:0,ex:"'Anrufen' forms its perfect with 'haben', so the past Konjunktiv II is 'hättest ... angerufen'."},
      {q:"Fill the gap: 'Wenn wir früher losgefahren ___, hätten wir den Zug erreicht.'",opts:["wären","hätten","würden","waren"],a:0,ex:"'Losfahren' is a verb of movement with 'sein' in the perfect, so it becomes 'wären ... losgefahren'."},
      {q:"Complete: 'Hätte ich das gewusst, ___'",opts:["wäre ich früher gegangen.","hätte ich früher gegangen.","würde ich früher gegangen.","dann ich wäre früher gegangen."],a:0,ex:"'Gehen' takes 'sein', so 'wäre ... gegangen'; after the condition clause the verb comes first."}
    ]},
    {t:"Reading: what if ...",s:"Reading",qs:[
      {q:"'Wenn ich damals Medizin studiert hätte, wäre ich heute Ärztin. Aber ich bereue nichts – ich liebe meinen Job als Lehrerin.' What is true?",opts:["She is a teacher with no regrets.","She is a doctor who loves her job.","She regrets not studying medicine.","She studied medicine in the past."],a:0,ex:"The past Konjunktiv II shows she did not study medicine; 'ich bereue nichts' means she has no regrets."},
      {q:"An email begins: 'Hätten Sie vielleicht einen Moment Zeit? Ich hätte eine kurze Frage zum Vertrag.' What does the writer want?",opts:["to ask a short question","to sign the contract","to cancel the contract","to book a meeting next week"],a:0,ex:"'Ich hätte eine kurze Frage' is a polite Konjunktiv II way to say 'I have a short question'."},
      {q:"'Er tut so, als ob er alles wüsste.' What does this sentence suggest?",opts:["He acts as if he knows everything.","He really knows everything.","He wants to learn everything.","He admits he knows nothing."],a:0,ex:"'So tun, als ob' + Konjunktiv II describes pretending: the appearance is not reality."}
    ]},
    {t:"Listening: dreams & regrets",s:"Listening",qs:[
      {q:"Listen. What would the speaker do after winning the lottery?",say:"Wenn ich im Lotto gewinnen würde, würde ich eine Weltreise machen.",opts:["travel around the world","buy a house","stop working","give the money away"],a:0,ex:"'Eine Weltreise machen' means to travel around the world; 'würde' marks it as hypothetical."},
      {q:"Listen. What is the speaker doing?",say:"An deiner Stelle würde ich den Job annehmen.",opts:["advising someone to take the job","turning down a job offer","applying for a job","quitting a job"],a:0,ex:"'An deiner Stelle würde ich ...' is a typical way to give advice: 'If I were you, I would ...'."},
      {q:"Listen. What actually happened?",say:"Wenn der Bus pünktlich gekommen wäre, hätte ich den Termin nicht verpasst.",opts:["The bus was late and the appointment was missed.","The bus was on time and the appointment was kept.","The speaker cancelled the appointment.","The bus was late, but the speaker made it."],a:0,ex:"The past Konjunktiv II describes the opposite of reality: the bus was late, so the appointment was missed."}
    ]},
    {t:"Polite requests & advice",s:"Speaking",qs:[
      {q:"You ask a stranger on the train to open the window. What do you say?",opts:["Würden Sie bitte das Fenster öffnen?","Öffnen Sie sofort das Fenster!","Wurden Sie das Fenster öffnen?","Werden Sie das Fenster öffnen?"],a:0,ex:"'Würden Sie bitte ...?' is a polite request; 'wurden' is past tense and 'werden' asks about the future."},
      {q:"A friend can't sleep well. Give advice.",opts:["Du solltest abends weniger Kaffee trinken.","Du solltest abends weniger Kaffee getrunken.","Du solltest abends weniger Kaffee zu trinken.","Du sollte abends weniger Kaffee trinken."],a:0,ex:"'Solltest' (Konjunktiv II of 'sollen') gives advice and takes a plain infinitive at the end."},
      {q:"You politely ask a colleague for a moment of their time. What do you say?",opts:["Hätten Sie einen Moment Zeit?","Hatten Sie einen Moment Zeit?","Haben Sie Zeit, schnell?","Hätten Sie einen Moment Zeiten?"],a:0,ex:"Konjunktiv II 'hätten' makes the question polite; 'hatten' is simply past tense."}
    ]},
    {t:"Writing about 'what if'",s:"Writing",qs:[
      {q:"Which unreal condition is written correctly?",opts:["Wenn ich mehr Geld hätte, würde ich ein Haus kaufen.","Wenn ich hätte mehr Geld, würde ich ein Haus kaufen.","Wenn ich mehr Geld hätte, ich würde ein Haus kaufen.","Wenn ich mehr Geld hätte, würde ich ein Haus gekauft."],a:0,ex:"'Wenn' sends 'hätte' to the end; the main clause then starts with 'würde' and ends with the infinitive."},
      {q:"Fill the gap: 'Mein Leben wäre ganz anders, wenn ich in Japan ___.'",opts:["aufgewachsen wäre","aufgewachsen hätte","aufwachsen wäre","aufgewachsen würde"],a:0,ex:"'Aufwachsen' takes 'sein' in the perfect, so the unreal past is 'aufgewachsen wäre'."},
      {q:"Fill the gap: 'Ich wünschte, ich ___ mehr Zeit für meine Familie.'",opts:["hätte","habe","hatte","hätten"],a:0,ex:"'Ich wünschte' expresses an unreal wish and is followed by Konjunktiv II: ich hätte."}
    ]},
    {t:"Politeness with Konjunktiv",s:"Culture",qs:[
      {q:"In a German café, which is the most polite way to order?",opts:["Ich hätte gern ein Stück Kuchen.","Ich will ein Stück Kuchen.","Gib mir ein Stück Kuchen.","Ein Stück Kuchen, aber schnell."],a:0,ex:"'Ich hätte gern' is the standard polite order; 'ich will' and commands sound rude to a waiter."},
      {q:"Why do Germans often say 'Könnten Sie ...?' instead of 'Können Sie ...?'",opts:["It sounds softer and more polite.","It refers to the past instead.","It sounds more urgent and direct.","It is more informal and casual."],a:0,ex:"Konjunktiv II adds distance and makes a request sound less like a demand."},
      {q:"What does the colloquial saying 'Hätte, hätte, Fahrradkette' mean?",opts:["It's no use dwelling on what might have been.","I would really like a new bicycle.","Let's go on a bike tour together.","Everything happened just as planned."],a:0,ex:"The rhyme mocks endless 'hätte' sentences: speculating about the past changes nothing."}
    ]},
    {t:"Hypotheticals review",s:"Review",qs:[
      {q:"'Könnte' is the Konjunktiv II form of which verb?",opts:["können","kennen","kommen","kaufen"],a:0,ex:"'Können' -> past 'konnte' -> Konjunktiv II 'könnte' (with umlaut)."},
      {q:"Fill the gap: 'Wenn es nicht regnen ___, gingen wir spazieren.'",opts:["würde","wurde","wird","werde"],a:0,ex:"The unreal condition needs Konjunktiv II: 'würde' + infinitive; 'wurde' is the past tense of 'werden'."},
      {q:"Fill the gap: 'Sie redet, als ob sie die Chefin ___.'",opts:["wäre","sein","gewesen","würde"],a:0,ex:"'Als ob' needs a conjugated verb at the end, usually Konjunktiv II: als ob sie die Chefin wäre."}
    ]},
    {t:"Challenge: Konjunktiv II",s:"Challenge",qs:[
      {q:"Fill the gap: 'Du hättest mich anrufen ___.'",opts:["sollen","gesollt","sollten","soll"],a:0,ex:"With another infinitive, modals use the double infinitive in the past: hättest ... anrufen sollen."},
      {q:"Fill the gap: 'Wenn ich das gewusst hätte, ___ ich dir geholfen.'",opts:["hätte","wäre","würde","hatte"],a:0,ex:"'Helfen' forms its perfect with 'haben', so the unreal past is 'hätte ... geholfen'."},
      {q:"Fill the gap: 'Er sieht aus, als ___ er die ganze Nacht nicht geschlafen.'",opts:["hätte","hat","wäre","würde"],a:0,ex:"After 'als' without 'ob', the verb comes right after it; 'schlafen' takes 'haben', so 'als hätte er'."}
    ]}
  ]
];
